/**
 * @class ElonSwapsClient
 * @description A client for interacting with the Elon Swaps API to manage escrow transactions.
 */
class ElonSwapsClient {
    /**
     * @private
     * @type {string}
     */
    #apiKey;

    /**
     * @private
     * @type {string}
     */
    #apiBaseUrl;

    /**
